const IMG={"logo": "data:image/jpeg;base64,", "kurkure": "data:image/jpeg;base64,", "afghani": "data:image/jpeg;base64,", "beet": "data:image/jpeg;base64,", "spinach": "data:image/jpeg;base64,", "veg": "data:image/jpeg;base64,", "peri": "data:image/jpeg;base64,", "garlic": "data:image/jpeg;base64,", "paneer": "data:image/jpeg;base64,", "cpaneer": "data:image/jpeg;base64,", "soya": "data:image/jpeg;base64,", "mdry": "data:image/jpeg;base64,", "mgravy": "data:image/jpeg;base64,", "mojito": "data:image/jpeg;base64,"},WA="919341974345",$=s=>document.querySelector(s),cart={};
const M=[
["Momos","Veg Momos","veg","Classic steamed momos with a soft vegetable filling.",[["10 pcs",74]]],
["Momos","Paneer Momos","paneer","Tender paneer filling in a delicate wrapper.",[["10 pcs",118]]],
["Momos","Garlic Steam","garlic","Steamed momos finished with a garlic-infused glaze.",[["10 pcs",105]]],
["Momos","Peri Peri","peri","Golden momos tossed in a bold peri peri seasoning.",[["10 pcs",116]]],
["Momos","Kurkure Momos","kurkure","Crisp, crunchy outside with a juicy filling.",[["8 pcs",138],["4 pcs",75]]],
["Momos","Afghani Momos","afghani","Herb-flecked momos in a rich, creamy style.",[["8 pcs",135],["4 pcs",75]]],
["Momos","Beetroot Momos","beet","Naturally coloured beetroot wrapper, vibrant and soft.",[["8 pcs",122],["4 pcs",65]]],
["Momos","Spinach Momos","spinach","Spinach wrapper with a fresh green finish.",[["8 pcs",122],["4 pcs",65]]],
["Indo-Chinese","Chilli Paneer","cpaneer","Paneer cubes tossed in a spicy chilli sauce.",[["12 pcs",190],["6 pcs",100]]],
["Indo-Chinese","Soya Chilli Dry","soya","Dry-style soya chunks in a glossy chilli glaze.",[["Full",150],["Half",90]]],
["Indo-Chinese","Manchurian Dry","mdry","Crisp vegetable manchurian in a dry, savoury toss.",[["10 pcs",228],["6 pcs",126]]],
["Indo-Chinese","Manchurian Gravy","mgravy","Served in a warm, flavourful gravy.",[["8 pcs",219],["4 pcs",110]]],
["Drinks","Mojito","mojito","A cool, refreshing mojito.",[["650 ml",138]]]];
const cats=["All",...new Set(M.map(m=>m[0]))];
document.querySelectorAll("[data-i]").forEach(i=>i.src=IMG[i.dataset.i]);
$("#mq").innerHTML=("<span>100% VEGETARIAN</span>Steamed<span>&bull;</span>Fried<span>&bull;</span>Afghani<span>&bull;</span>Peri Peri<span>&bull;</span>Kurkure<span>&bull;</span>Order on WhatsApp").repeat(8);
function show(c){$("#tabs").innerHTML=cats.map(x=>`<button class="${x==c?'on':''}" onclick="show('${x}')">${x}</button>`).join("");
$("#grid").innerHTML=M.filter(m=>c=="All"||m[0]==c).map(m=>`<div class="card rv"><div class="ph"><span class="vg"></span><img src="${IMG[m[2]]}" alt="${m[1]}" loading="lazy"></div><div class="bd"><h3>${m[1]}</h3><p>${m[3]}</p>${m[4].map(o=>`<div class="o"><span>${o[0]}</span><b>Rs ${o[1]}</b><button class="add" onclick="add('${m[1]}','${o[0]}',${o[1]})">Add</button></div>`).join("")}</div></div>`).join("");obs()}
function add(n,l,p){const k=n+"|"+l;cart[k]=cart[k]?{...cart[k],q:cart[k].q+1}:{n,l,p,q:1};draw();$("#fab").animate([{transform:"scale(1.15)"},{transform:"scale(1)"}],250)}
function chg(k,d){cart[k].q+=d;if(cart[k].q<1)delete cart[k];draw()}
function draw(){const a=Object.entries(cart);let t=0,c=0;$("#ls").innerHTML=a.length?a.map(([k,v])=>{t+=v.p*v.q;c+=v.q;return`<div class="ln"><span>${v.n} (${v.l})<br><small>Rs ${v.p*v.q}</small></span><span><button onclick="chg('${k}',-1)">-</button> ${v.q} <button onclick="chg('${k}',1)">+</button></span></div>`}).join(""):"<p style='color:#888;padding:20px 0'>Your order is empty. Add something from the menu.</p>";
$("#t").textContent="Rs "+t;$("#n").textContent=c;
const msg="Hello Johar Momos, I would like to order:\n"+a.map(([k,v])=>`- ${v.n} (${v.l}) x${v.q} = Rs ${v.p*v.q}`).join("\n")+`\n\nTotal: Rs ${t}\nName:\nAddress:`;
$("#send").href=`https://wa.me/${WA}?text=`+encodeURIComponent(a.length?msg:"Hello Johar Momos, I would like to place an order.")}
$("#fab").onclick=()=>$("#dr").classList.add("on");$("#cl").onclick=e=>{e.preventDefault();$("#dr").classList.remove("on")};$("#dr").onclick=e=>{if(e.target.id=="dr")$("#dr").classList.remove("on")};
document.querySelectorAll("[data-wa]").forEach(a=>a.href=`https://wa.me/${WA}?text=`+encodeURIComponent("Hello Johar Momos, I would like to place an order."));
const io=new IntersectionObserver(e=>e.forEach(x=>{if(x.isIntersecting){x.target.classList.add("in");io.unobserve(x.target);x.target.querySelectorAll("[data-n]").forEach(el=>{const n=+el.dataset.n;let i=0;const t=setInterval(()=>{i+=Math.max(1,n/40);if(i>=n){i=n;clearInterval(t)}el.textContent=Math.round(i)},30)})}}),{threshold:.12});
function obs(){document.querySelectorAll(".rv:not(.in)").forEach(el=>io.observe(el))}
addEventListener("scroll",()=>{$("#bar").style.width=scrollY/(document.body.scrollHeight-innerHeight)*100+"%"});
show("All");draw();obs();
